/// RFC 6962 section 2.1.2 verifier, written independently of the
/// recursive proof producer: fold the leaf hash with the audit path via
/// the index bits (left subtree when the bit is 0), without padding or
/// copying leaves for non-power-of-two sizes.
fn verify_path(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
    assert_eq!(path.len(), if n <= 1 { 0 } else { usize::BITS as usize - (n - 1).leading_zeros() as usize });
    let mut fn_index = m;
    let mut sn = n;
    let mut node = {
        let mut input = vec![0x00];
        input.extend_from_slice(leaf);
        sha256(&input)
    };
    for sibling in path {
        if sn == 0 {
            panic!("path longer than tree height");
        }
        if fn_index == sn {
            // The current subtree is the complete right-hand subtree:
            // its boundary moves up as-is and this sibling is on the
            // left, which the parity bit already encodes.
        }
        if fn_index & 1 == 1 || fn_index == sn {
            let mut input = Vec::with_capacity(65);
            input.push(0x01);
            input.extend_from_slice(sibling);
            input.extend_from_slice(&node);
            node = sha256(&input);
        } else {
            let mut input = Vec::with_capacity(65);
            input.push(0x01);
            input.extend_from_slice(&node);
            input.extend_from_slice(sibling);
            node = sha256(&input);
        }
        fn_index >>= 1;
        sn >>= 1;
    }
    node
}

#[test]
fn audit_paths_verify_for_every_position_and_size() {
    // Include duplicate content on purpose: proofs must be per position.
    let leaves: Vec<&[u8]> = vec![
        b"same", b"b", b"", b"d", b"same", b"f\r", b"\xff\x00", b"h", b"i", b"same",
    ];
    for n in 1..=leaves.len() {
        let batch = &leaves[..n];
        let root = mth(batch);
        for m in 0..n {
            let path = audit_path(batch, m);
            // One record -> empty path; otherwise path length is the
            // tree height ceil(log2(n)).
            let expected_len = if n <= 1 { 0 } else { usize::BITS as usize - (n - 1).leading_zeros() as usize };
            assert_eq!(path.len(), expected_len, "n={n}, m={m}");
            assert_eq!(
                hex_of(&verify_path(batch[m], m, n, &path)),
                hex_of(&root),
                "proof must reconstruct root for n={n}, m={m}"
            );
        }
    }
}

#[test]
fn duplicate_records_get_distinct_position_proofs() {
    let leaves: Vec<&[u8]> = vec![b"x", b"x", b"x"];
    let p0 = audit_path(&leaves, 0);
    let p1 = audit_path(&leaves, 1);
    let p2 = audit_path(&leaves, 2);
    // Different positions must not collapse to the "first occurrence".
    assert_ne!(p0, p1);
    assert_ne!(p1, p2);
    for (m, path) in [(0, p0), (1, p1), (2, p2)] {
        assert_eq!(hex_of(&verify_path(b"x", m, 3, &path)), hex_of(&mth(&leaves)));
    }
}

