                let mut input = vec![0x01];
                input.extend_from_slice(sibling);
                input.extend_from_slice(&node);
                sha256(&input)
            }
        };
    }
    assert_ne!(hex_of(&node), hex_of(&root), "proof for m=1 must not verify at m=0");
